public class EnumDemo2 {
    enum Size { REGULAR, LARGE, PARTY }

    public static void main(String[] args) {
        Size s = Size.LARGE;
        System.out.print("Price of pizza is ");

        switch (s) {
            case REGULAR:
                System.out.println("381.00");
                break;
            case LARGE:
                System.out.println("602.00");
                break;
            case PARTY:
                System.out.println("799.00");
                break;
        }
    }
}

Size s = Size.LARGE;
double price = switch (s) {
    case REGULAR -> 381.00;
    case LARGE -> 602.00;
    case PARTY -> 799.00;
};
System.out.println(price);   // 602.0
